import { Fragment, useCallback, useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { Link, Navigate, Route, Routes, useLocation, useNavigate, useParams } from 'react-router-dom';
import { QRCodeSVG } from 'qrcode.react';
import { api, ApiError, dateOnly, dateTime, materialLabels, materials, money, post, routeFor, type Profile } from './api';

// Login com Google desativado. Para reativar: trocar para true aqui e ligar GOOGLE_LOGIN_ATIVO=true no backend.
const GOOGLE_LOGIN_ATIVO: boolean = false;

type ToastState = { message: string; kind?: 'error' | 'success' };
const toastEvent = new EventTarget();
function useToast() {
  const [toast, setToast] = useState<ToastState | null>(null);
  useEffect(() => { const h = (e: Event) => { const c = (e as CustomEvent<ToastState>).detail; setToast(c); window.setTimeout(() => setToast(null), 4500); }; toastEvent.addEventListener('toast', h); return () => toastEvent.removeEventListener('toast', h); }, []);
  return toast;
}
function notify(message: string, kind: ToastState['kind'] = 'success') { toastEvent.dispatchEvent(new CustomEvent('toast', { detail: { message, kind } })); }

const navItems: Record<Profile['tipo'], { id: string; label: string; icon: string }[]> = {
  cliente: [
    { id: 'dashboard', label: 'Início', icon: '⌂' }, { id: 'saldo', label: 'Meu saldo', icon: '◉' },
    { id: 'historico', label: 'Histórico', icon: '▤' }, { id: 'qrcode', label: 'Ler QR Code', icon: '▦' },
    { id: 'meu-codigo', label: 'Meu código', icon: '▧' }, { id: 'como-funciona', label: 'Como funciona', icon: '♻' },
    { id: 'loja-papelaria', label: 'JS Papelaria', icon: '▣' },
  ],
  loja: [
    { id: 'dashboard', label: 'Início', icon: '⌂' }, { id: 'scan', label: 'Scan QR', icon: '▦' },
    { id: 'troca', label: 'Registrar troca', icon: '♻' }, { id: 'descontar', label: 'Descontar moedas', icon: '◉' },
    { id: 'historico', label: 'Histórico', icon: '▤' }, { id: 'vendas', label: 'Vendas c/ moedas', icon: '▥' },
    { id: 'perfil', label: 'Perfil da loja', icon: '⌂' },
  ],
  admin: [
    { id: 'dashboard', label: 'Dashboard', icon: '⌂' }, { id: 'usuarios', label: 'Usuários', icon: '♙' },
    { id: 'parceiros', label: 'Lojas parceiras', icon: '⌂' }, { id: 'resgates', label: 'Resgates', icon: '↘' }, { id: 'transacoes', label: 'Transações', icon: '↔' },
    { id: 'monitor-qr', label: 'Monitor QR', icon: '▦' }, { id: 'relatorios', label: 'Relatórios', icon: '▥' },
    { id: 'auditoria', label: 'Auditoria', icon: '⌕' }, { id: 'configuracoes', label: 'Configurações', icon: '⚙' },
  ],
};
const roleName = { cliente: 'Área do cliente', loja: 'Painel da loja', admin: 'Administração' };

export default function App() {
  const [profile, setProfile] = useState<Profile | null>(null);
  const [ready, setReady] = useState(false);
  const toast = useToast();
  const location = useLocation();
  const loadProfile = useCallback(async () => {
    try { const d = await api<{ usuario: Profile }>('/auth/verificar'); setProfile(d.usuario); }
    catch { setProfile(null); }
    finally { setReady(true); }
  }, []);
  useEffect(() => { void loadProfile(); }, [loadProfile, location.pathname]);
  const logout = async () => { try { await post('/auth/logout'); } catch { /* sessão pode já ter expirado */ } setProfile(null); window.location.assign('/login'); };
  return <>
    <Routes>
      <Route path="/" element={<Navigate to={profile ? routeFor(profile) : '/login'} replace />} />
      <Route path="/login" element={ready && profile ? <Navigate to={routeFor(profile)} replace /> : <AuthPage mode="login" onAuthenticated={loadProfile} />} />
      <Route path="/cadastro" element={ready && profile ? <Navigate to={routeFor(profile)} replace /> : <AuthPage mode="signup" onAuthenticated={loadProfile} />} />
      <Route path="/mfa" element={<MfaPage onAuthenticated={loadProfile} />} />
      <Route path="/mfa/celular" element={<MfaPage phone onAuthenticated={loadProfile} />} />
      <Route path="/admin-mfa" element={<Navigate to="/mfa" replace />} />
      <Route path="/admin-mfa/celular" element={<Navigate to="/mfa/celular" replace />} />
      <Route path="/verificar-email" element={<EmailVerificationPage onAuthenticated={loadProfile} />} />
      <Route path="/privacidade" element={<PrivacyPage />} />
      <Route path="/app/:role/*" element={!ready ? <LoadingPage /> : !profile ? <Navigate to="/login" replace /> : <RoleGuard profile={profile} onLogout={logout} />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
    <CookieConsent />
    {toast && <div role="status" className={`toast ${toast.kind || ''}`}>{toast.message}</div>}
  </>;
}

function RoleGuard({ profile, onLogout }: { profile: Profile; onLogout: () => void }) {
  const { role } = useParams();
  if (role !== profile.tipo) return <Navigate to={routeFor(profile)} replace />;
  return <Dashboard profile={profile} onLogout={onLogout} />;
}
function LoadingPage() { return <div className="startup-loading"><img src="/logo.png" alt="CrisoVerde" /><span className="spinner" />Carregando CrisoVerde…</div>; }

const isMobileDevice = () => typeof window !== 'undefined' && (Boolean(window.matchMedia?.('(pointer: coarse)').matches) || /Android|iPhone|iPad|iPod/i.test(navigator.userAgent));
const authenticatorStoreUrl = () => (/iPhone|iPad|iPod/i.test(navigator.userAgent) ? 'https://apps.apple.com/app/google-authenticator/id388497605' : 'https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2');
async function copyText(text: string) {
  try { await navigator.clipboard.writeText(text); return true; }
  catch {
    try { const t = document.createElement('textarea'); t.value = text; t.setAttribute('readonly', ''); t.className = 'sr-only'; document.body.appendChild(t); t.select(); const ok = document.execCommand('copy'); t.remove(); return ok; }
    catch { return false; }
  }
}
function CopyButton({ text, label = 'Copiar', done = 'Copiado!', className = 'button subtle' }: { text: string; label?: string; done?: string; className?: string }) {
  const [ok, setOk] = useState(false);
  const click = async () => { if (await copyText(text)) { setOk(true); window.setTimeout(() => setOk(false), 2000); } else notify('Não foi possível copiar. Selecione o texto e copie manualmente.', 'error'); };
  return <button type="button" className={className} onClick={() => void click()}>{ok ? done : label}</button>;
}
type MfaSetup = { secret: string; otpauth_url: string };
function MfaPage({ onAuthenticated, phone = false }: { onAuthenticated: () => Promise<void>; phone?: boolean }) {
  const navigate = useNavigate(); const location = useLocation();
  const novaConta = Boolean((location.state as { novaConta?: boolean } | null)?.novaConta);
  const [setup, setSetup] = useState<MfaSetup | null>(null);
  const [code, setCode] = useState(''); const [recovery, setRecovery] = useState<string[]>([]);
  const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [appMissing, setAppMissing] = useState(false);
  const loadSetup = useCallback((regenerar = false) => api<MfaSetup>('/auth/mfa/setup', { method: 'POST', body: JSON.stringify({ regenerar }) }).then(setSetup).catch(e => setError(e instanceof Error ? e.message : 'Não foi possível iniciar a configuração.')), []);
  useEffect(() => { void loadSetup(); }, [loadSetup]);
  const confirm = async (e: FormEvent) => { e.preventDefault(); setBusy(true); setError(''); try { const d = await post<{ codigos_recuperacao: string[] }>('/auth/mfa/confirm', { codigo: code }); setRecovery(d.codigos_recuperacao); await onAuthenticated(); } catch (e) { setError(e instanceof Error ? e.message : 'Código inválido.'); } finally { setBusy(false); } };
  const finish = async () => { if (novaConta) { try { await post('/auth/verificar-email/solicitar', {}); } catch { /* o reenvio fica disponível na tela de confirmação */ } navigate('/verificar-email'); return; } navigate('/'); };
  // Se o app autenticador abrir, a página vai para segundo plano. Se continuar visível após ~2s, o app provavelmente não está instalado.
  const tryOpenApp = () => { let left = false; const onChange = () => { if (document.visibilityState === 'hidden') left = true; }; document.addEventListener('visibilitychange', onChange); window.setTimeout(() => { document.removeEventListener('visibilitychange', onChange); if (!left) setAppMissing(true); }, 2000); };
  const regenerate = () => { setError(''); setCode(''); setSetup(null); void loadSetup(true); };
  const codeForm = <form className="stack" onSubmit={confirm}><Field label="Código de seis dígitos" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} autoComplete="one-time-code" value={code} onChange={v => setCode(v.replace(/\D/g, '').slice(0, 6))} required /><button className="button primary full" disabled={busy || code.length !== 6}>{busy ? 'Validando…' : 'Ativar MFA'}</button></form>;
  return <main className="auth-page"><section className="auth-card"><Brand /><h1>Proteja sua conta</h1>{error && <div className="alert error" role="alert">{error}</div>}
    {recovery.length ? <>
      <p>Salve estes códigos em local seguro. Cada código pode ser usado uma única vez e, depois, você pode revê-los em Segurança, no menu.</p>
      <ul className="recovery-codes">{recovery.map(x => <li key={x}><code>{x}</code></li>)}</ul>
      <div className="button-row"><CopyButton text={recovery.join('\n')} label="Copiar todos os códigos" done="Códigos copiados!" /></div>
      <button className="button primary full" onClick={() => void finish()}>Salvei os códigos e continuar</button>
    </> : setup && phone ? <>
      <p>Você está no celular, então não precisa ler QR Code. Siga os passos:</p>
      <ol className="mfa-steps">
        <li><strong>Copie a chave</strong><div className="key-box"><code>{groupKey(setup.secret)}</code></div><CopyButton text={setup.secret} label="Copiar chave" done="Chave copiada!" className="button primary full" /></li>
        <li><strong>Abra seu app autenticador</strong><a className="button subtle full" href={setup.otpauth_url} onClick={tryOpenApp}>Abrir no app autenticador</a>{appMissing && <div className="alert info" role="status"><p>O app autenticador não abriu. Instale o Google Authenticator (é grátis), abra, toque em “Inserir chave de configuração”, cole a chave que você copiou e escolha “Baseada em tempo”. Esta página continua aberta.</p><a className="button primary full" href={authenticatorStoreUrl()} target="_blank" rel="noopener noreferrer">Instalar o Google Authenticator</a></div>}<small className="muted">Se nada abrir, instale o Google Authenticator, Microsoft Authenticator ou Authy, toque em “Inserir chave de configuração”, cole a chave e escolha “Baseada em tempo”. Não tem o app? <a href={authenticatorStoreUrl()} target="_blank" rel="noopener noreferrer">Instalar o Google Authenticator</a>.</small></li>
        <li><strong>Volte aqui e digite o código</strong>{codeForm}</li>
      </ol>
      <div className="button-row"><button type="button" className="button subtle small" onClick={regenerate}>Gerar nova chave</button><Link className="button subtle small" to="/mfa">Estou no computador (QR Code)</Link></div>
    </> : setup ? <>
      <p>Adicione este autenticador ao app de sua preferência e informe o código de seis dígitos para concluir.</p>
      <div className="qr-center"><QRCodeSVG value={setup.otpauth_url} size={192} /><p><strong>Chave de configuração</strong><br /><code>{groupKey(setup.secret)}</code></p><CopyButton text={setup.secret} label="Copiar chave" done="Chave copiada!" /></div>
      {codeForm}
      <div className="button-row"><Link className="button subtle small" to="/mfa/celular">Estou no celular (sem QR Code)</Link><button type="button" className="button subtle small" onClick={regenerate}>Gerar nova chave</button></div>
    </> : <LoadingBlock />}
  </section></main>;
}
const groupKey = (k: string) => k.replace(/(.{4})/g, '$1 ').trim();
type RecoveryCode = { codigo: string; usado: boolean };
function ResetMfaModal({ target, onClose }: { target: { tipo: 'usuario' | 'loja'; id: number; nome: string }; onClose: () => void }) {
  const [senha, setSenha] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const submit = async (e: FormEvent) => { e.preventDefault(); setBusy(true); setError(''); try { await post('/admin/mfa/resetar', { tipo: target.tipo, id: target.id, senha }); notify('MFA resetado. No próximo login a pessoa configura um autenticador novo.'); onClose(); } catch (e) { setError(e instanceof Error ? e.message : 'Não foi possível resetar.'); } finally { setBusy(false); } };
  return <div className="modal-backdrop" role="dialog" aria-modal="true"><form className="modal-card" onSubmit={submit}><button type="button" className="close-button" onClick={onClose} aria-label="Fechar">×</button><h2>Resetar MFA</h2><p className="muted">Remove o segundo fator de <strong>{target.nome}</strong> e encerra as sessões dessa conta. Use só se a pessoa perdeu o celular e os códigos de recuperação.</p><ErrorBlock error={error} /><div className="stack"><Field label="Sua senha de administrador" type="password" autoComplete="current-password" value={senha} onChange={setSenha} required /><button className="button warning full" disabled={busy || !senha}>{busy ? 'Resetando…' : 'Resetar MFA'}</button></div></form></div>;
}
function SecurityPage() {
  return <><PageTitle title="Segurança" description="Seu segundo fator de autenticação (MFA) e os códigos de recuperação." /><RecoveryCodesPanel /></>;
}
function RecoveryCodesPanel() {
  const [senha, setSenha] = useState(''); const [codes, setCodes] = useState<RecoveryCode[] | null>(null);
  const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const run = async (acao: 'listar' | 'regenerar') => {
    if (acao === 'regenerar' && !window.confirm('Os códigos atuais deixarão de valer. Gerar novos?')) return;
    setBusy(true); setError('');
    try { const d = await post<{ codigos: RecoveryCode[] }>('/auth/mfa/codigos', { senha, ...(/^\d{6}$/.test(senha) ? { codigo: senha } : {}), acao }); setCodes(d.codigos); setSenha(''); if (acao === 'regenerar') notify('Novos códigos gerados. Os anteriores deixaram de valer.'); }
    catch (e) { setError(e instanceof Error ? e.message : 'Não foi possível carregar os códigos.'); }
    finally { setBusy(false); }
  };
  return <Panel title="Códigos de recuperação do MFA"><p className="muted">Use um código de recuperação no campo de MFA do login quando estiver sem o app autenticador. Cada código vale uma vez.</p>
    <ErrorBlock error={error} />
    {codes ? <><ul className="recovery-codes">{codes.map(c => <li key={c.codigo} className={c.usado ? 'used' : ''}><code>{c.codigo}</code>{c.usado && <small>usado</small>}</li>)}</ul>
      <div className="button-row"><CopyButton text={codes.filter(c => !c.usado).map(c => c.codigo).join('\n')} label="Copiar não usados" done="Copiado!" /><button type="button" className="button danger" onClick={() => setCodes(null)}>Ocultar</button></div></>
    : <form className="inline-form" onSubmit={e => { e.preventDefault(); void run('listar'); }}><Field label="Sua senha (ou o código do autenticador, se você entra só com Google)" type="password" autoComplete="current-password" value={senha} onChange={setSenha} required /><button className="button primary" disabled={busy || !senha}>{busy ? 'Verificando…' : 'Ver códigos'}</button></form>}
    {codes && <form className="inline-form" onSubmit={e => { e.preventDefault(); void run('regenerar'); }}><Field label="Senha (ou código do autenticador) para gerar novos códigos" type="password" autoComplete="current-password" value={senha} onChange={setSenha} required /><button className="button warning" disabled={busy || !senha}>Gerar novos códigos</button></form>}
  </Panel>;
}

function EmailVerificationPage({ onAuthenticated }: { onAuthenticated: () => Promise<void> }) {
  const navigate = useNavigate();
  const [code, setCode] = useState(''); const [message, setMessage] = useState('Se o envio de e-mail estiver configurado, você receberá um código em instantes.'); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [done, setDone] = useState(false);
  const run = async (fn: () => Promise<void>) => { setBusy(true); setError(''); try { await fn(); } catch (e) { setError(e instanceof Error ? e.message : 'Não foi possível concluir.'); } finally { setBusy(false); } };
  const confirm = (e: FormEvent) => { e.preventDefault(); void run(async () => { const d = await post<{ mensagem: string }>('/auth/verificar-email/confirmar', { codigo: code }); setMessage(d.mensagem); setDone(true); }); };
  return <main className="auth-page"><section className="auth-card"><Brand /><h1>Confirme seu e-mail</h1><p>Informe o código enviado para a sua conta. A confirmação é necessária para usar QR Codes e solicitar resgates.</p>{message && <div className="alert info">{message}</div>}{error && <div role="alert" className="alert error">{error}</div>}{!done && <><form className="stack" onSubmit={confirm}><Field label="Código de seis dígitos" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} value={code} onChange={v => setCode(v.replace(/\D/g, '').slice(0, 6))} required /><button className="button primary full" disabled={busy || code.length !== 6}>{busy ? 'Verificando…' : 'Confirmar e-mail'}</button></form><button className="button subtle full" disabled={busy} onClick={() => void run(async () => { const d = await post<{ mensagem: string }>('/auth/verificar-email/solicitar', {}); setMessage(d.mensagem); })}>Reenviar código</button></>}{done && <button className="button primary full" onClick={() => { void onAuthenticated().then(() => navigate('/')); }}>Continuar</button>}</section></main>;
}

function Brand({ compact = false }: { compact?: boolean }) { return <div className={`brand ${compact ? 'compact' : ''}`}><div className="brand-mark">♻</div><span>CrisoVerde</span></div>; }
function AuthPage({ mode, onAuthenticated }: { mode: 'login' | 'signup'; onAuthenticated: () => Promise<void> }) {
  const navigate = useNavigate(); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [phone, setPhone] = useState(''); const [password, setPassword] = useState(''); const [mfaCode, setMfaCode] = useState('');
  const [showPassword, setShowPassword] = useState(false); const [accepted, setAccepted] = useState(false); const [recover, setRecover] = useState(false);
  const [splashReady, setSplashReady] = useState(false); const [progress, setProgress] = useState(0);
  const [googleUnavailable, setGoogleUnavailable] = useState(false);
  useEffect(() => {
    setSplashReady(false); setProgress(0);
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduceMotion) { setProgress(100); setSplashReady(true); return; }
    const duration = 2200; const start = performance.now(); let frame = 0;
    const tick = (now: number) => {
      const value = Math.min(100, ((now - start) / duration) * 100);
      setProgress(value);
      if (value >= 100) setSplashReady(true); else frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    const failsafe = window.setTimeout(() => { setProgress(100); setSplashReady(true); }, 4000);
    return () => { cancelAnimationFrame(frame); clearTimeout(failsafe); };
  }, [mode]);
  const submit = async (e: FormEvent) => {
    e.preventDefault(); setError('');
    setBusy(true);
    try {
      if (mode === 'signup' && !accepted) throw new Error('Leia e aceite a Política de Privacidade para continuar.');
      const resultado = await post<any>(mode === 'login' ? '/auth/login' : '/auth/cadastro', mode === 'login' ? { email, senha: password, ...(mfaCode ? { codigo_mfa: mfaCode } : {}) } : { nome: name, email, telefone: phone, senha: password });
      if (resultado?.mfa_setup_required) { navigate(isMobileDevice() ? '/mfa/celular' : '/mfa', { state: { novaConta: mode === 'signup' } }); return; }
      if (mode === 'signup') { await post('/auth/verificar-email/solicitar', {}); navigate('/verificar-email'); await onAuthenticated(); return; }
      await onAuthenticated(); navigate('/');
    } catch (e) { setError(e instanceof Error ? e.message : 'Não foi possível entrar.'); }
    finally { setBusy(false); }
  };
  const googleCred = useRef<string | null>(null); const mfaRef = useRef(''); const [googlePending, setGooglePending] = useState(false);
  useEffect(() => { mfaRef.current = mfaCode; }, [mfaCode]);
  const submitGoogle = async (credential: string) => {
    setBusy(true); setError('');
    try {
      const resultado = await post<any>('/auth/google', { credential, ...(mfaRef.current ? { codigo_mfa: mfaRef.current } : {}) });
      googleCred.current = null; setGooglePending(false);
      if (resultado?.mfa_setup_required) { navigate(isMobileDevice() ? '/mfa/celular' : '/mfa'); return; }
      await onAuthenticated(); navigate('/');
    }
    catch (e) { if (e instanceof ApiError && e.data?.mfa_required) { googleCred.current = credential; setGooglePending(true); } setError(e instanceof Error ? e.message : 'Não foi possível entrar com o Google.'); }
    finally { setBusy(false); }
  };
  useEffect(() => {
    if (!GOOGLE_LOGIN_ATIVO || mode !== 'login') return;
    let active = true;
    setGoogleUnavailable(false);
    api<{ clientId?: string }>('/auth/google/client-id').then(async ({ clientId }) => {
      if (!clientId) { setGoogleUnavailable(true); return; }
      if (!active || !clientId) return;
      const w = window as any;
      if (!w.google?.accounts?.id) await new Promise<void>((resolve) => { const s = document.createElement('script'); s.src = 'https://accounts.google.com/gsi/client'; s.async = true; s.onload = () => resolve(); s.onerror = () => resolve(); document.head.append(s); });
      if (!active || !w.google?.accounts?.id) { setGoogleUnavailable(true); return; }
      w.google.accounts.id.initialize({ client_id: clientId, callback: (r: { credential: string }) => void submitGoogle(r.credential) });
      const el = document.getElementById('google-auth-button'); if (el) { w.google.accounts.id.renderButton(el, { theme: 'outline', size: 'large', shape: 'pill', text: 'continue_with', width: 320 }); setGoogleUnavailable(false); }
    }).catch(() => { if (active) setGoogleUnavailable(true); });
    return () => { active = false; };
  }, [mode]);
  const field = (label: string, value: string, onChange: (v: string) => void, _n: number, props: Record<string, unknown> = {}) => <Fragment key={label}><label className="legacy-label">{label}</label><div className="legacy-field"><input value={value} onChange={e => onChange(e.target.value)} {...props} /></div></Fragment>;
  return <main className={`legacy-auth-screen ${splashReady ? 'ready' : 'intro'} ${mode}`}>
    <div className="legacy-leaves" aria-hidden="true"><svg width="180" height="180" viewBox="0 0 40 40"><path d="M20 4C20 4 8 14 8 24a12 12 0 0 0 24 0C32 14 20 4 20 4z" /></svg><svg width="120" height="120" viewBox="0 0 40 40"><path d="M20 4C20 4 8 14 8 24a12 12 0 0 0 24 0C32 14 20 4 20 4z" /></svg></div>
    <div className="legacy-logo"><img src="/logo.png" alt="CrisoVerde" /></div>
    <div className="legacy-splash" aria-hidden="true"><p className="legacy-tagline">Sustentabilidade que gera recompensas</p><div className="legacy-progress"><div className="legacy-progress-row"><span>Carregando</span><span>{Math.round(progress)}%</span></div><div className="legacy-track"><progress className="legacy-fill" max={100} value={progress} /></div></div></div>
    <form className={`legacy-login ${mode === 'signup' ? 'legacy-signup' : ''}`} onSubmit={submit}>
      <h2>{mode === 'login' ? 'Bem-vindo de volta' : 'Crie sua conta'}</h2>
      <p className="legacy-sub">{mode === 'login' ? 'Entre na sua conta para continuar' : 'Cadastre-se para começar sua jornada sustentável'}</p>
      {error && <div role="alert" className="legacy-error visible">{error}</div>}
      {mode === 'signup' && <>{field('Nome completo', name, setName, 2, { autoComplete: 'name', required: true, maxLength: 120, placeholder: 'Seu nome completo' })}{field('Telefone (opcional)', phone, setPhone, 4, { autoComplete: 'tel', maxLength: 50, placeholder: '(00) 00000-0000' })}</>}
      {field('E-mail', email, setEmail, mode === 'login' ? 2 : 6, { type: 'email', autoComplete: 'email', required: true, maxLength: 255, placeholder: 'seu@email.com', inputMode: 'email' })}
      <label className="legacy-label">Senha</label>
      <div className="legacy-field"><input type={showPassword ? 'text' : 'password'} value={password} onChange={e => setPassword(e.target.value)} autoComplete={mode === 'login' ? 'current-password' : 'new-password'} minLength={mode === 'signup' ? 8 : undefined} maxLength={mode === 'signup' ? 72 : 200} required placeholder="Sua senha" /><button type="button" className="legacy-eye" onClick={() => setShowPassword(x => !x)} aria-label={showPassword ? 'Ocultar senha' : 'Mostrar senha'}>{showPassword ? <svg viewBox="0 0 24 24"><path d="M3 3l18 18M10.6 10.6a2 2 0 002.8 2.8M9.9 5.2A11 11 0 0112 5c7 0 11 7 11 7a18 18 0 01-3.2 4.1M6.2 6.2C3.4 8 1 12 1 12s4 7 11 7c1.1 0 2.2-.2 3.2-.6" /></svg> : <svg viewBox="0 0 24 24"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" /><circle cx="12" cy="12" r="3" /></svg>}</button></div>
      {mode === 'login' && <><label className="legacy-label">Código MFA (se você já ativou)</label><div className="legacy-field"><input inputMode="text" autoComplete="one-time-code" maxLength={12} value={mfaCode} onChange={e => setMfaCode(e.target.value.replace(/[^a-zA-Z0-9]/g, '').slice(0, 12).toUpperCase())} placeholder="Código do app ou de recuperação" /></div>{googlePending && <button type="button" className="legacy-submit" disabled={busy || !mfaCode} onClick={() => googleCred.current && void submitGoogle(googleCred.current)}>Continuar com Google usando este código</button>}</>}
      {mode === 'signup' && <label className="legacy-terms"><input type="checkbox" checked={accepted} onChange={e => setAccepted(e.target.checked)} required /><span>Li a <Link to="/privacidade">Política de Privacidade</Link> e estou ciente do uso necessário de cookies para sessão.</span></label>}
      {mode === 'login' && <div className="legacy-forgot"><button type="button" className="legacy-link" onClick={() => setRecover(true)}>Esqueci a senha</button></div>}
      <button className="legacy-submit" disabled={busy}>{busy ? 'Aguarde…' : mode === 'login' ? 'Entrar' : 'Criar conta'}</button>
      {GOOGLE_LOGIN_ATIVO && mode === 'login' && <><div className="legacy-or">ou</div><div id="google-auth-button" className="legacy-google" />{googleUnavailable && <p className="legacy-google-unavailable">Login com Google indisponível no momento.</p>}</>}
      <div className="legacy-signup-link">{mode === 'login' ? 'Não tem uma conta?' : 'Já tem cadastro?'} <Link to={mode === 'login' ? '/cadastro' : '/login'}>{mode === 'login' ? 'Criar conta' : 'Entrar'}</Link></div>
      <p className="legacy-foot">© CrisoVerde — Juntos por um planeta mais verde · <Link to="/privacidade">Privacidade</Link></p>
    </form>
    {recover && <RecoveryModal onClose={() => setRecover(false)} />}
  </main>;
}
function Field({ label, value, onChange, type = 'text', ...props }: { label: string; value: string; onChange: (v: string) => void; type?: string; [key: string]: any }) { return <label className="field-label">{label}<input type={type} value={value} onChange={e => onChange(e.target.value)} {...props} /></label>; }

function RecoveryModal({ onClose }: { onClose: () => void }) {
  const [step, setStep] = useState(0); const [email, setEmail] = useState(''); const [code, setCode] = useState(''); const [resetToken, setResetToken] = useState('');
  const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const run = async (fn: () => Promise<void>) => { setBusy(true); setError(''); try { await fn(); } catch (e) { setError(e instanceof Error ? e.message : 'Falha na solicitação.'); } finally { setBusy(false); } };
  return <div className="modal-backdrop legacy-recovery" role="presentation" onMouseDown={e => e.target === e.currentTarget && onClose()}><section className="modal-card" role="dialog" aria-modal="true" aria-labelledby="recovery-title"><button className="close-button" onClick={onClose} aria-label="Fechar">×</button>
    <h2 id="recovery-title">{['Recuperar senha', 'Verifique seu e-mail', 'Defina uma nova senha', 'Tudo certo'][step]}</h2><p className="muted">{['Informe seu e-mail para receber um código de verificação.', 'Digite o código de seis dígitos recebido.', 'Use pelo menos 8 caracteres, com letras e números.', 'Sua senha foi redefinida.'][step]}</p>
    {error && <div className="alert error" role="alert">{error}</div>}
    {step === 0 && <form className="stack" onSubmit={e => { e.preventDefault(); void run(async () => { await post('/auth/forgot-password', { email }); setStep(1); }); }}><Field label="E-mail" type="email" value={email} onChange={setEmail} required /><button className="button primary full" disabled={busy}>{busy ? 'Enviando…' : 'Enviar código'}</button></form>}
    {step === 1 && <form className="stack" onSubmit={e => { e.preventDefault(); void run(async () => { const d = await post<{ resetToken: string }>('/auth/verify-reset-code', { email, codigo: code }); setResetToken(d.resetToken); setStep(2); }); }}><Field label="Código de 6 dígitos" inputMode="numeric" pattern="[0-9]{6}" maxLength={6} value={code} onChange={v => setCode(v.replace(/\D/g, '').slice(0, 6))} required /><button className="button primary full" disabled={busy}>{busy ? 'Verificando…' : 'Verificar código'}</button><button className="button subtle full" type="button" disabled={busy} onClick={() => void run(async () => { await post('/auth/forgot-password', { email }); notify('Se este e-mail estiver cadastrado, um novo código foi enviado.'); })}>Reenviar código</button></form>}
    {step === 2 && <form className="stack" onSubmit={e => { e.preventDefault(); void run(async () => { if (password !== confirm) throw new Error('As senhas não coincidem.'); await post('/auth/reset-password', { resetToken, novaSenha: password }); setStep(3); }); }}><Field label="Nova senha" type="password" autoComplete="new-password" minLength={8} maxLength={72} value={password} onChange={setPassword} required /><Field label="Confirme a nova senha" type="password" autoComplete="new-password" minLength={8} maxLength={72} value={confirm} onChange={setConfirm} required /><button className="button primary full" disabled={busy}>{busy ? 'Salvando…' : 'Redefinir senha'}</button></form>}
    {step === 3 && <button className="button primary full" onClick={onClose}>Concluir</button>}
  </section></div>;
}

function Dashboard({ profile, onLogout }: { profile: Profile; onLogout: () => void }) {
  const location = useLocation(); const section = location.pathname.split('/').filter(Boolean).at(-1) || 'dashboard'; const navigate = useNavigate(); const items = navItems[profile.tipo];
  const current = section === 'seguranca' ? { id: 'seguranca', label: 'Segurança', icon: '⛨' } : items.find(x => x.id === section) || items[0];
  return <div className="app-shell"><aside className="sidebar"><Link to={routeFor(profile)} className="brand-link"><Brand /></Link><div className="sidebar-label">MENU PRINCIPAL</div><nav>{items.map(item => <Link key={item.id} to={`${routeFor(profile)}/${item.id}`} className={`nav-item ${section === item.id ? 'active' : ''}`}><span>{item.icon}</span>{item.label}</Link>)}</nav><div className="sidebar-bottom"><Link to={`${routeFor(profile)}/seguranca`} className={`nav-item ${section === 'seguranca' ? 'active' : ''}`}><span>⛨</span>Segurança (MFA)</Link><Link to="/privacidade" className="nav-item"><span>◌</span>Privacidade e cookies</Link><button className="nav-item logout" onClick={onLogout}><span>↪</span>Sair da conta</button></div></aside>
    <main className="main-area"><header className="topbar"><div><span className="role-kicker">{roleName[profile.tipo]}</span><h1>{current.label}</h1></div><div className="user-chip"><div className="avatar">{profile.nome.slice(0, 1).toUpperCase()}</div><div><strong>{profile.nome}</strong><span>{profile.email}</span></div><button className="mobile-logout" onClick={onLogout} aria-label="Sair da conta" title="Sair da conta">↪</button></div></header><div className="content-area"><RoleContent key={`${profile.tipo}-${section}`} profile={profile} section={section} onNavigate={id => navigate(`${routeFor(profile)}/${id}`)} /></div><footer className="app-footer">CrisoVerde · <Link to="/privacidade">Privacidade e cookies</Link><button className="inline-link" onClick={() => window.dispatchEvent(new Event('open-cookie-settings'))}>Preferências de cookies</button></footer></main></div>;
}

function RoleContent({ profile, section, onNavigate }: { profile: Profile; section: string; onNavigate: (id: string) => void }) {
  if (section === 'seguranca') return <SecurityPage />;
  if (profile.tipo === 'cliente') return <CustomerContent section={section} profile={profile} onNavigate={onNavigate} />;
  if (profile.tipo === 'loja') return <StoreContent section={section} profile={profile} />;
  return <AdminContent section={section} />;
}

function PageTitle({ title, description, action }: { title: string; description?: string; action?: ReactNode }) { return <div className="page-heading"><div><h2>{title}</h2>{description && <p>{description}</p>}</div>{action}</div>; }
function Panel({ title, children, action }: { title?: string; children: ReactNode; action?: ReactNode }) { return <section className="panel">{(title || action) && <div className="panel-heading">{title && <h3>{title}</h3>}{action}</div>}{children}</section>; }
function Stat({ label, value, icon, caption }: { label: string; value: ReactNode; icon: string; caption?: string }) { return <div className="stat-card"><span className="stat-icon">{icon}</span><div><div className="stat-label">{label}</div><strong className="stat-value">{value}</strong>{caption && <small>{caption}</small>}</div></div>; }
function Table({ columns, rows, empty = 'Nenhum registro encontrado.' }: { columns: string[]; rows: ReactNode[][]; empty?: string }) { return <div className="table-wrap"><table><thead><tr>{columns.map(c => <th key={c}>{c}</th>)}</tr></thead><tbody>{rows.length ? rows.map((row, i) => <tr key={i}>{row.map((c, j) => <td key={j}>{c}</td>)}</tr>) : <tr><td className="empty-cell" colSpan={columns.length}>{empty}</td></tr>}</tbody></table></div>; }
function useLoad<T>(path: string | null) { const [data, setData] = useState<T | null>(null); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const reload = useCallback(async () => { if (!path) return; setLoading(true); setError(''); try { setData(await api<T>(path)); } catch (e) { setError(e instanceof Error ? e.message : 'Erro ao carregar.'); } finally { setLoading(false); } }, [path]); useEffect(() => { void reload(); }, [reload]); return { data, error, loading, reload, setData }; }
function ErrorBlock({ error }: { error: string }) { return error ? <div className="alert error" role="alert">{error}</div> : null; }
function LoadingBlock() { return <div className="loading-inline"><span className="spinner" />Carregando…</div>; }
function QRScanner({ onResult }: { onResult: (value: string) => void }) {
  const id = useRef(`qr-${Math.random().toString(36).slice(2)}`); const scanner = useRef<any>(null); const [running, setRunning] = useState(false); const [error, setError] = useState('');
  const stop = useCallback(async () => { if (scanner.current) { try { await scanner.current.stop(); await scanner.current.clear(); } catch {} scanner.current = null; } setRunning(false); }, []);
  useEffect(() => () => { if (scanner.current) void scanner.current.stop().catch(() => {}); }, []);
  const start = async () => { setError(''); try { const { Html5Qrcode } = await import('html5-qrcode'); const s = new Html5Qrcode(id.current); scanner.current = s; await s.start({ facingMode: 'environment' }, { fps: 10, qrbox: { width: 230, height: 230 } }, value => { void stop(); onResult(value); }, () => {}); setRunning(true); } catch { scanner.current = null; setError('Não foi possível abrir a câmera. Confira a permissão do navegador ou digite o código manualmente.'); } };
  return <div className="scanner-card"><div id={id.current} className="scanner-view"/><ErrorBlock error={error} /><div className="button-row"><button className="button primary" onClick={() => void (running ? stop() : start())}>{running ? 'Parar câmera' : 'Iniciar scanner'}</button></div><p className="fine-print">A câmera só é ativada quando você solicita. Em produção, o navegador exige HTTPS.</p></div>;
}

function CustomerContent({ section, profile, onNavigate }: { section: string; profile: Profile; onNavigate: (id: string) => void }) {
  const wallet = useLoad<any>('/cliente/carteira'); const [historyPath, setHistoryPath] = useState('/cliente/historico'); const history = useLoad<any[]>(historyPath);
  const [token, setToken] = useState(''); const [validated, setValidated] = useState<any>(null); const [busy, setBusy] = useState(false);
  const [amount, setAmount] = useState(''); const [qrData, setQrData] = useState<any>(null); const [filter, setFilter] = useState('');
  useEffect(() => { if (section === 'meu-codigo') void api<any>('/cliente/meu-qr').then(setQrData).catch(e => notify(e.message, 'error')); }, [section]);
  const scanValue = (value: string) => { try { const p = JSON.parse(value); setToken(String(p.token || value).trim()); } catch { setToken(value.trim()); } };
  const validate = async (e?: FormEvent) => { e?.preventDefault(); setBusy(true); setValidated(null); try { const d = await post<any>('/qr/validar', { token }); setValidated({ ...d, token }); } catch (e) { notify(e instanceof Error ? e.message : 'QR inválido.', 'error'); } finally { setBusy(false); } };
  const confirm = async () => { if (!validated) return; setBusy(true); try { const d = await post<any>('/qr/confirmar', { token: validated.token, id_transacao: validated.id_transacao }); notify(d.mensagem || 'Transação confirmada.'); setValidated(null); setToken(''); await wallet.reload(); await history.reload(); } catch (e) { notify(e instanceof Error ? e.message : 'Não foi possível confirmar.', 'error'); } finally { setBusy(false); } };
  const redeem = async (e: FormEvent) => { e.preventDefault(); setBusy(true); try { const d = await post<any>('/cliente/resgatar', { valor: Number(amount), forma: 'pix' }); notify(d.mensagem || 'Resgate solicitado.'); setAmount(''); await wallet.reload(); await history.reload(); } catch (e) { notify(e instanceof Error ? e.message : 'Resgate não concluído.', 'error'); } finally { setBusy(false); } };
  const w = wallet.data || {};
  if (section === 'dashboard') return <>
    <PageTitle title={`Olá, ${profile.nome.split(' ')[0]} 👋`} description="Acompanhe suas recompensas e o impacto da reciclagem." />
    {wallet.loading ? <LoadingBlock /> : <><ErrorBlock error={wallet.error} /><div className="stats-grid"><Stat label="Saldo disponível" value={money(w.saldo)} icon="◉" caption="Crisomoedas" /><Stat label="Total ganho" value={money(w.total_ganho)} icon="↗" /><Stat label="Materiais reciclados" value={`${Number(w.total_reciclado_kg || 0).toFixed(1)} kg`} icon="♻" /><Stat label="CO₂ estimado evitado" value={`~${(Number(w.total_reciclado_kg || 0) * 0.5).toFixed(1)} kg`} icon="✳" /></div></>}
    <Panel title="Atalhos"><div className="shortcut-grid"><button onClick={() => onNavigate('qrcode')}><span>▦</span><strong>Ler QR Code</strong><small>Confirmar crédito ou desconto</small></button><button onClick={() => onNavigate('meu-codigo')}><span>▧</span><strong>Meu código</strong><small>Identificação na loja parceira</small></button><button onClick={() => onNavigate('historico')}><span>▤</span><strong>Ver histórico</strong><small>Acompanhe suas movimentações</small></button></div></Panel>
    <HistoryTable history={history} />
  </>;
  if (section === 'saldo') return <><PageTitle title="Meu saldo" description="Seu saldo e as movimentações da sua carteira." />{wallet.loading ? <LoadingBlock /> : <><ErrorBlock error={wallet.error} /><div className="stats-grid"><Stat label="Saldo disponível" value={money(w.saldo)} icon="◉" /><Stat label="Saldo em carência" value={money(w.saldo_pendente)} icon="◷" /><Stat label="Total ganho" value={money(w.total_ganho)} icon="↗" /><Stat label="Total utilizado" value={money(w.total_utilizado)} icon="↘" /></div></>}<Panel title="Solicitar resgate"><p className="muted">Créditos recentes ficam disponíveis após o período de carência. Pedidos de resgate passam por aprovação.</p><form className="inline-form" onSubmit={redeem}><label className="field-label">Valor<input type="number" min="0.01" max={Math.min(100, Number(w.saldo || 0))} step="0.01" value={amount} onChange={e => setAmount(e.target.value)} required /></label><button className="button primary" disabled={busy}>{busy ? 'Processando…' : 'Solicitar resgate'}</button></form></Panel><HistoryTable history={history} /></>;
  if (section === 'historico') return <><PageTitle title="Histórico" description="Créditos e débitos registrados na sua conta." /><div className="toolbar"><label className="field-label compact-label">Tipo<select value={filter} onChange={e => { setFilter(e.target.value); setHistoryPath(`/cliente/historico${e.target.value ? `?tipo=${e.target.value}` : ''}`); }}><option value="">Todos</option><option value="credito">Créditos</option><option value="debito">Débitos</option></select></label><button className="button subtle" onClick={() => void history.reload()}>Atualizar</button></div><HistoryTable history={history} /></>;
  if (section === 'qrcode') return <><PageTitle title="Ler QR Code" description="Leia o QR da loja e confira os detalhes antes de confirmar." /><div className="two-column"><Panel title="Scanner"><QRScanner onResult={scanValue} /></Panel><Panel title="Digitar código"><form className="stack" onSubmit={validate}><label className="field-label">Token do QR<textarea rows={4} value={token} onChange={e => setToken(e.target.value)} required placeholder="Cole o token ou o conteúdo do QR Code" /></label><button className="button primary" disabled={busy || !token}>{busy ? 'Validando…' : 'Validar QR'}</button></form></Panel></div>{validated && <Panel title={validated.tipo === 'debito' ? 'Confirmar desconto' : 'Confirmar reciclagem'}><div className="confirm-card"><div><span className="muted">Loja</span><strong>{validated.nome_loja || `Loja #${validated.id_loja}`}</strong></div><div><span className="muted">{validated.tipo === 'debito' ? 'Produto/serviço' : 'Materiais'}</span><strong>{validated.produto || validated.descricao_material || '—'}</strong></div><div><span className="muted">Valor</span><strong className={validated.tipo === 'debito' ? 'negative' : 'positive'}>{validated.tipo === 'debito' ? '−' : '+'}{money(validated.valor)}</strong></div><div><span className="muted">Expira</span><strong>{dateTime(validated.expira_em)}</strong></div></div><div className="button-row"><button className="button primary" disabled={busy} onClick={() => void confirm()}>{busy ? 'Confirmando…' : 'Confirmar transação'}</button><button className="button subtle" onClick={() => setValidated(null)}>Cancelar</button></div></Panel>}</>;
  if (section === 'meu-codigo') return <><PageTitle title="Meu código" description="Mostre este código para a loja identificar sua conta." /><Panel><div className="qr-center">{qrData ? <QRCodeSVG value={qrData.qr_data} size={240} level="M" /> : <LoadingBlock />}<p>Este código de identificação é temporário. Gere outro quando necessário.</p>{qrData?.validade_seg && <small>Validade: {qrData.validade_seg} segundos</small>}<button className="button primary" onClick={() => void api<any>('/cliente/meu-qr').then(setQrData).catch(e => notify(e.message, 'error'))}>Gerar novo código</button></div></Panel></>;
  if (section === 'como-funciona') return <><PageTitle title="Como funciona" description="Recicle materiais nas lojas parceiras e receba créditos na sua carteira." /><div className="steps-grid">{[['01', 'Separe os materiais', 'Leve papelão, plástico, alumínio ou vidro a uma loja parceira.'], ['02', 'A loja registra a troca', 'A loja informa as quantidades e gera um QR Code de crédito.'], ['03', 'Leia e confira', 'Use o scanner para validar o QR e confira a loja e o valor.'], ['04', 'Confirme a transação', 'Depois da sua confirmação, os créditos entram no saldo e no histórico.']].map(([n, title, text]) => <Panel key={n}><span className="step-no">{n}</span><h3>{title}</h3><p className="muted">{text}</p></Panel>)}</div><Panel title="Conversão atual"><div className="material-rates">{materials.map((m, i) => <div key={m}><span>{['📦', '🧴', '🥫', '🍾'][i]}</span><strong>{materialLabels[m]}</strong><small>Taxa configurada pela administração</small></div>)}</div><p className="fine-print">O valor final é calculado no servidor com as taxas vigentes da plataforma.</p></Panel></>;
  if (section === 'loja-papelaria') return <><PageTitle title="JS Papelaria" description="Catálogo apresentado no aplicativo original." /><div className="alert info">Este catálogo era demonstrativo e não possui integração de estoque/preços no backend recebido. A confirmação real de descontos é feita pela loja via QR Code; use “Ler QR Code” para finalizar uma transação registrada.</div><ProductCatalog saldo={Number(w.saldo || 0)} /></>;
  return <Navigate to="/app/cliente/dashboard" replace />;
}
function HistoryTable({ history }: { history: ReturnType<typeof useLoad<any[]>> }) {
  if (history.loading) return <Panel title="Movimentações"><LoadingBlock /></Panel>;
  const rows = Array.isArray(history.data) ? history.data.map((r: any) => [<strong>#{r.id}</strong>, <span className={r.tipo === 'credito' ? 'positive' : 'negative'}>{r.tipo === 'credito' ? 'Crédito' : 'Débito'}</span>, r.materiais || r.materiais_desc || r.produto || r.forma || '—', money(r.valor), dateTime(r.criado_em)]) : [];
  return <Panel title="Movimentações"><ErrorBlock error={history.error} /><Table columns={['Código', 'Tipo', 'Descrição', 'Valor', 'Data']} rows={rows} /></Panel>;
}
function ProductCatalog({ saldo }: { saldo: number }) {
  const items = [
    ['📓', 'Caderno Universitário', '200 folhas, capa dura, várias cores', 18.9], ['✏️', 'Caixa de Lápis (12un)', 'Lápis de cor, madeira certificada', 12.5],
    ['🖊️', 'Kit Canetas (6un)', 'Esferográficas coloridas, ponta fina', 9.9], ['🎒', 'Estojo Escolar', 'Duplo, zíper resistente, várias cores', 22],
    ['🎽', 'Mochila Escolar', '20L, reforçada, porta notebook', 89.9], ['📐', 'Kit Acessórios', 'Régua, compasso, transferidor e esquadro', 14.5],
    ['🟥', 'Borracha Branca (4un)', 'Macia, não mancha, longa duração', 5], ['🖍️', 'Marca-texto (4 cores)', 'Amarelo, rosa, verde e azul', 8],
  ] as const;
  const [selected, setSelected] = useState<(typeof items)[number] | null>(null); const [confirmed, setConfirmed] = useState(false);
  const coins = Math.floor(saldo / 0.25); const tiers = [{ moedas: 5, pct: 5 }, { moedas: 10, pct: 8 }, { moedas: 20, pct: 10 }, { moedas: 40, pct: 13 }, { moedas: 60, pct: 15 }, { moedas: 100, pct: 20 }];
  const discount = [...tiers].reverse().find(t => coins >= t.moedas)?.pct || 0; const price = selected ? selected[3] * (1 - discount / 100) : 0;
  return <><Panel title="Descontos progressivos"><div className="discount-summary"><div><span className="muted">Suas CrisoMoedas</span><strong>{coins}</strong></div><div><span className="muted">Desconto disponível</span><strong>{discount}%</strong></div></div><div className="tier-list">{tiers.map(t => <div key={t.moedas}><span>{t.moedas} CrisoMoedas</span><strong>{t.pct}%</strong><small>{coins >= t.moedas ? 'Desbloqueado' : `Faltam ${t.moedas - coins}`}</small></div>)}</div><p className="fine-print">Conversão exibida pelo catálogo original: cada R$ 0,25 no saldo equivale a 1 CrisoMoeda.</p></Panel><div className="product-grid">{items.map(item => <article className="product-card" key={item[1]}><span>{item[0]}</span><h3>{item[1]}</h3><p>{item[2]}</p><div className="product-price-row">{discount > 0 && <del>{money(item[3])}</del>}<strong>{money(item[3] * (1 - discount / 100))}</strong></div>{discount > 0 && <span className="discount-pill">−{discount}% com CrisoMoedas</span>}<button className="button subtle full" onClick={() => { if (!discount) { notify('Acumule pelo menos 5 CrisoMoedas para desbloquear um desconto.', 'error'); return; } setSelected(item); setConfirmed(false); }}>Usar desconto</button></article>)}</div>{selected && <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && setSelected(null)}><section className="modal-card"><button className="close-button" onClick={() => setSelected(null)}>×</button>{confirmed ? <><h2>Oferta pronta</h2><p className="muted">Desconto de {discount}% calculado para {selected[1]}. Apresente esta oferta na loja. O catálogo original não envia pedidos nem debita o saldo; para uma transação real, a loja gera um QR de desconto que você confirma no painel.</p><button className="button primary full" onClick={() => setSelected(null)}>Concluir</button></> : <><span className="product-emoji">{selected[0]}</span><h2>Confirmar desconto?</h2><p>{selected[1]}</p><div className="price-breakdown"><span>Preço original<strong>{money(selected[3])}</strong></span><span>Desconto ({discount}%)<strong>−{money(selected[3] - price)}</strong></span><span>Você paga<strong>{money(price)}</strong></span></div><p className="fine-print">O catálogo original não registra a compra nem desconta Crisomoedas.</p><button className="button primary full" onClick={() => setConfirmed(true)}>Preparar oferta para apresentar</button></>}</section></div>}</>;
}

function StoreContent({ section, profile }: { section: string; profile: Profile }) {
  const [rates, setRates] = useState<Record<string, number>>({ papelao: 7, plastico: 10, aluminio: 6, vidro: 4 });
  const [quantities, setQuantities] = useState<Record<string, string>>({ papelao: '', plastico: '', aluminio: '', vidro: '' });
  const [product, setProduct] = useState(''); const [debitValue, setDebitValue] = useState('');
  const [generated, setGenerated] = useState<any>(null); const [busy, setBusy] = useState(false); const [search, setSearch] = useState(''); const [searchResults, setSearchResults] = useState<any[]>([]); const [selectedCustomer, setSelectedCustomer] = useState<any>(null);
  const [days, setDays] = useState('30'); const [month, setMonth] = useState(new Date().toISOString().slice(0, 7));
  const dash = useLoad<any>('/loja/dashboard'); const profileData = useLoad<any>(section === 'perfil' ? '/loja/perfil' : null);
  const hist = useLoad<any>(section === 'historico' ? `/loja/historico?dias=${days}` : null); const sales = useLoad<any>(section === 'vendas' ? `/loja/vendas?mes=${month}` : null);
  useEffect(() => { void api<Record<string, number>>('/config/taxas').then(setRates).catch(() => {}); }, []);
  useEffect(() => { if (search.trim().length < 3) { setSearchResults([]); return; } const t = window.setTimeout(() => { void api<any>(`/loja/clientes/buscar?busca=${encodeURIComponent(search)}&limite=5`).then(d => setSearchResults(d.usuarios || [])).catch(e => notify(e.message, 'error')); }, 300); return () => window.clearTimeout(t); }, [search]);
  const total = useMemo(() => materials.reduce((sum, m) => sum + Math.floor(Number(quantities[m] || 0) / Math.max(1, Number(rates[m] || 1))) * 0.25, 0), [quantities, rates]);
  const generate = async (kind: 'credito' | 'debito') => {
    setBusy(true); setGenerated(null);
    try { const payload = kind === 'credito' ? { tipo: kind, materiais: Object.fromEntries(materials.map(m => [m, Number(quantities[m] || 0)])) } : { tipo: kind, produto: product, valor: Number(debitValue) };
      const d = await post<any>('/qr/gerar', payload); setGenerated({ ...d, tipo: kind, valor: kind === 'credito' ? total : Number(debitValue), descricao: kind === 'credito' ? materials.filter(m => Number(quantities[m] || 0) > 0).map(m => `${materialLabels[m]}: ${quantities[m]}`).join(', ') : product });
      notify('QR Code gerado. Peça ao cliente para ler e confirmar.');
    } catch (e) { notify(e instanceof Error ? e.message : 'Não foi possível gerar o QR.', 'error'); }
    finally { setBusy(false); }
  };
  if (section === 'dashboard') { const d = dash.data || {}; return <><PageTitle title={`Olá, ${profile.nome.split(' ')[0]}`} description="Resumo das operações da sua loja parceira." />{dash.loading ? <LoadingBlock /> : <><ErrorBlock error={dash.error} /><div className="stats-grid"><Stat label="Trocas registradas" value={d.total_trocas || 0} icon="♻" /><Stat label="Materiais reciclados" value={`${Number(d.total_kg || 0).toFixed(1)} kg`} icon="▤" /><Stat label="Créditos distribuídos" value={money(d.total_creditos)} icon="↗" /><Stat label="CO₂ estimado evitado" value={`~${Number(d.co2_evitado || 0).toFixed(1)} kg`} icon="✳" /></div><Panel title="Últimas trocas"><Table columns={['Cliente', 'Materiais', 'Créditos', 'Data']} rows={(d.ultimas_trocas || []).map((x: any) => [x.cliente || '—', x.materiais || '—', money(x.valor_total), dateTime(x.data)])} /></Panel></>}</>; }
  if (section === 'scan') return <><PageTitle title="Identificar cliente" description="Escaneie o código de identificação do cliente ou informe o código manualmente." /><div className="two-column"><Panel title="Scanner do cliente"><QRScanner onResult={value => { let qrData = value; try { const j = JSON.parse(value); qrData = j.qr_data || value; } catch {} void post<any>('/cliente/identificar', { qr_data: qrData }).then(setSelectedCustomer).catch(e => notify(e.message, 'error')); }} /></Panel><Panel title="Busca manual"><form className="stack" onSubmit={async e => { e.preventDefault(); try { const d = await api<any>(`/loja/clientes/buscar?busca=${encodeURIComponent(search)}&limite=5`); setSearchResults(d.usuarios || []); } catch (e) { notify(e instanceof Error ? e.message : 'Busca falhou.', 'error'); } }}><Field label="Nome ou e-mail" value={search} onChange={setSearch} minLength={3} /><button className="button primary">Buscar clientes</button></form><CustomerSearch results={searchResults} onPick={setSelectedCustomer} /></Panel></div>{selectedCustomer && <Panel title="Cliente identificado"><div className="confirm-card"><div><span className="muted">Nome</span><strong>{selectedCustomer.nome}</strong></div><div><span className="muted">Saldo atual</span><strong>{selectedCustomer.saldo == null ? '—' : money(selectedCustomer.saldo)}</strong></div><div><span className="muted">Trocas anteriores</span><strong>{selectedCustomer.total_trocas ?? '—'}</strong></div></div><p className="fine-print">O QR de crédito permanece vinculado à confirmação feita pelo cliente. Este painel não altera o destinatário do QR.</p></Panel>}</>;
  if (section === 'troca') return <><PageTitle title="Registrar troca" description="Informe materiais recebidos e gere o QR para o cliente confirmar o crédito." /><Panel title="Cliente (opcional)"><label className="field-label">Buscar por nome ou e-mail<input value={search} onChange={e => setSearch(e.target.value)} minLength={3} placeholder="Digite um e-mail completo ou 3 letras do nome" /></label><CustomerSearch results={searchResults} onPick={setSelectedCustomer} />{selectedCustomer && <div className="selected-line"><strong>{selectedCustomer.nome}</strong><span>{selectedCustomer.saldo == null ? '—' : money(selectedCustomer.saldo)} atual · {selectedCustomer.total_trocas == null ? '—' : selectedCustomer.total_trocas} troca(s)</span><button className="inline-link" onClick={() => setSelectedCustomer(null)}>Remover</button></div>}</Panel><Panel title="Materiais entregues"><div className="material-input-grid">{materials.map((m, i) => <label className="material-input" key={m}><span>{['📦', '🧴', '🥫', '🍾'][i]}</span><strong>{materialLabels[m]}</strong><small>{rates[m] || '—'} unidades = R$ 0,25</small><input type="number" min="0" max="1000" step="1" value={quantities[m]} onChange={e => setQuantities(q => ({ ...q, [m]: e.target.value }))} placeholder="Quantidade" /></label>)}</div><div className="total-line"><span>Crédito calculado</span><strong>{money(total)}</strong></div><button className="button primary" disabled={busy || total <= 0} onClick={() => void generate('credito')}>{busy ? 'Gerando…' : 'Gerar QR de crédito'}</button></Panel>{generated && <GeneratedQR data={generated} onNew={() => setGenerated(null)} />}</>;
  if (section === 'descontar') return <><PageTitle title="Descontar moedas" description="Gere um QR de débito para o cliente confirmar a compra ou serviço." /><Panel title="Dados da venda"><form className="stack form-narrow" onSubmit={e => { e.preventDefault(); void generate('debito'); }}><Field label="Produto ou serviço" value={product} onChange={setProduct} maxLength={255} required placeholder="Ex.: Caderno ecológico" /><Field label="Valor em Crisomoedas" type="number" value={debitValue} onChange={setDebitValue} min="0.01" max="100000" step="0.01" required /><button className="button primary" disabled={busy}>{busy ? 'Gerando…' : 'Gerar QR de desconto'}</button></form></Panel>{generated && <GeneratedQR data={generated} onNew={() => setGenerated(null)} />}</>;
  if (section === 'historico') return <><PageTitle title="Histórico de trocas" description="Trocas de reciclagem confirmadas na sua loja." /><div className="toolbar"><label className="field-label compact-label">Período<select value={days} onChange={e => setDays(e.target.value)}><option value="30">Últimos 30 dias</option><option value="7">Últimos 7 dias</option><option value="90">Últimos 90 dias</option></select></label><button className="button subtle" onClick={() => void hist.reload()}>Atualizar</button></div>{hist.loading ? <LoadingBlock /> : <Panel><ErrorBlock error={hist.error} /><Table columns={['ID', 'Cliente', 'Materiais', 'Créditos', 'Data']} rows={(hist.data?.trocas || []).map((x: any) => [`#${x.id}`, x.cliente || '—', x.materiais || '—', money(x.valor_total), dateTime(x.data)])} /></Panel>}</>;
  if (section === 'vendas') return <><PageTitle title="Vendas com Crisomoedas" description="Resumo dos descontos confirmados pelos clientes." /><div className="toolbar"><label className="field-label compact-label">Mês<input type="month" value={month} onChange={e => setMonth(e.target.value)} /></label><button className="button subtle" onClick={() => void sales.reload()}>Atualizar</button></div>{sales.loading ? <LoadingBlock /> : <><ErrorBlock error={sales.error} /><div className="stats-grid"><Stat label="Vendas no período" value={sales.data?.total_vendas || 0} icon="▤" /><Stat label="Total descontado" value={money(sales.data?.total_debitado)} icon="↘" /></div><Panel title="Vendas registradas"><Table columns={['ID', 'Cliente', 'Produto/serviço', 'Valor', 'Data']} rows={(sales.data?.vendas || []).map((x: any) => [`#${x.id}`, x.cliente || '—', x.produto || '—', money(x.valor), dateTime(x.data)])} /></Panel></>}</>;
  if (section === 'perfil') return <><PageTitle title="Perfil da loja" description="Informações cadastrais vinculadas à sua conta." />{profileData.loading ? <LoadingBlock /> : <Panel title="Dados da loja"><ErrorBlock error={profileData.error} /><div className="details-grid">{[['Nome', profileData.data?.nome], ['Responsável', profileData.data?.responsavel], ['E-mail', profileData.data?.email], ['Telefone', profileData.data?.telefone], ['Endereço', profileData.data?.endereco], ['Status', profileData.data?.status], ['Membro desde', dateOnly(profileData.data?.criado_em)]].map(([k, v]) => <div key={k}><span>{k}</span><strong>{v || '—'}</strong></div>)}</div></Panel>}</>;
  return <Navigate to="/app/loja/dashboard" replace />;
}
function CustomerSearch({ results, onPick }: { results: any[]; onPick: (v: any) => void }) { return results.length ? <div className="search-results">{results.map((u: any) => <button key={u.id} onClick={() => onPick(u)}><span className="avatar small">{String(u.nome || '?').slice(0, 1)}</span><span><strong>{u.nome}</strong><small>{u.total_trocas == null ? '—' : `${u.total_trocas} troca(s)`}</small></span><strong>{u.saldo == null ? '—' : money(u.saldo)}</strong></button>)}</div> : null; }
function GeneratedQR({ data, onNew }: { data: any; onNew: () => void }) {
  const [seconds, setSeconds] = useState(() => Math.max(0, Math.floor((new Date(data.expira_em).getTime() - Date.now()) / 1000)));
  useEffect(() => { const i = window.setInterval(() => setSeconds(Math.max(0, Math.floor((new Date(data.expira_em).getTime() - Date.now()) / 1000))), 1000); return () => window.clearInterval(i); }, [data.expira_em]);
  return <Panel title="QR Code gerado"><div className="qr-center"><QRCodeSVG value={data.token} size={220} level="M" /><strong>{data.tipo === 'credito' ? '+' : '−'}{money(data.valor)}</strong><span>{data.descricao}</span><span className={seconds < 10 ? 'negative' : 'muted'}>{seconds > 0 ? `Expira em ${seconds}s` : 'Tempo expirado'}</span><p>Mostre este código ao cliente. A transação só é registrada depois da validação e confirmação pelo cliente.</p><small>Transação #{data.id_transacao}</small><button className="button subtle" onClick={onNew}>Gerar outro QR</button></div></Panel>;
}

function AdminContent({ section }: { section: string }) {
  const paths: Record<string, string> = { dashboard: '/admin/dashboard', usuarios: '/admin/usuarios', parceiros: '/admin/lojas', resgates: '/admin/resgates', transacoes: '/admin/transacoes', 'monitor-qr': '/admin/qrcode/listar', auditoria: '/admin/auditoria' };
  const [page, setPage] = useState(1); const [status, setStatus] = useState(''); const [type, setType] = useState(''); const [days, setDays] = useState('30'); const [qrStatus, setQrStatus] = useState(''); const [actionFilter, setActionFilter] = useState(''); const [month, setMonth] = useState(new Date().toISOString().slice(0, 7));
  const [storeForm, setStoreForm] = useState({ nome: '', responsavel: '', email: '', telefone: '', endereco: '', senha: '' }); const [showStoreForm, setShowStoreForm] = useState(false);
  const [taxes, setTaxes] = useState({ papelao: 7, plastico: 10, aluminio: 6, vidro: 4 }); const [qrConfig, setQrConfig] = useState({ expiracao_segundos: 60, max_tentativas: 5 });
  const [report, setReport] = useState<any>(null); const [reportError, setReportError] = useState(''); const [reportLoading, setReportLoading] = useState(false);
  const query = new URLSearchParams(); query.set('pagina', String(page));
  if (section === 'usuarios' && status) query.set('status', status);
  if (section === 'transacoes') { if (type) query.set('tipo', type); if (days) query.set('dias', days); }
  if (section === 'monitor-qr') { query.set('por_pagina', '15'); if (qrStatus) query.set('status', qrStatus); }
  if (section === 'auditoria' && actionFilter) query.set('acao', actionFilter);
  const dataPath = paths[section] ? `${paths[section]}${section === 'dashboard' || section === 'parceiros' ? '' : `?${query.toString()}`}` : null;
  const result = useLoad<any>(section === 'configuracoes' ? '/admin/configuracoes/taxas' : dataPath);
  const pendingStores = useLoad<any>(section === 'parceiros' ? '/admin/lojas/pendentes' : null);
  useEffect(() => { setPage(1); }, [section, status, type, days, qrStatus, actionFilter]);
  useEffect(() => { if (result.data && section === 'configuracoes') setTaxes({ papelao: result.data.papelao ?? 7, plastico: result.data.plastico ?? 10, aluminio: result.data.aluminio ?? 6, vidro: result.data.vidro ?? 4 }); }, [result.data, section]);
  const loadReport = useCallback(async () => { if (section !== 'relatorios') return; setReportLoading(true); setReportError(''); try { setReport(await api<any>(`/admin/relatorios/lojas?mes=${month}`)); } catch (e) { setReportError(e instanceof Error ? e.message : 'Não foi possível carregar.'); } finally { setReportLoading(false); } }, [section, month]);
  useEffect(() => { void loadReport(); }, [loadReport]);
  const [resetMfa, setResetMfa] = useState<{ tipo: 'usuario' | 'loja'; id: number; nome: string } | null>(null);
  const act = async (path: string, method = 'POST', body?: unknown) => { if (!window.confirm('Confirma esta ação?')) return; try { await api(path, { method, ...(body ? { body: JSON.stringify(body) } : {}) }); notify('Ação concluída.'); await result.reload(); } catch (e) { notify(e instanceof Error ? e.message : 'Não foi possível concluir.', 'error'); } };
  const saveStore = async (e: FormEvent) => { e.preventDefault(); try { await post('/admin/lojas', storeForm); notify('Loja cadastrada.'); setShowStoreForm(false); setStoreForm({ nome: '', responsavel: '', email: '', telefone: '', endereco: '', senha: '' }); await result.reload(); } catch (e) { notify(e instanceof Error ? e.message : 'Não foi possível cadastrar.', 'error'); } };
  const saveTaxes = async (e: FormEvent) => { e.preventDefault(); try { await post('/admin/configuracoes/taxas', taxes); notify('Taxas atualizadas.'); } catch (e) { notify(e instanceof Error ? e.message : 'Não foi possível salvar.', 'error'); } };
  const saveQr = async (e: FormEvent) => { e.preventDefault(); try { await post('/admin/configuracoes-qr', qrConfig); notify('Configurações de QR salvas.'); } catch (e) { notify(e instanceof Error ? e.message : 'Não foi possível salvar.', 'error'); } };
  if (section === 'dashboard') { const d = result.data || {}; return <><PageTitle title="Visão geral" description="Indicadores e atividade recente da plataforma." />{result.loading ? <LoadingBlock /> : <><ErrorBlock error={result.error} /><div className="stats-grid"><Stat label="Clientes" value={d.total_clientes || 0} icon="♙" /><Stat label="Lojas parceiras" value={d.total_lojas || 0} icon="⌂" /><Stat label="Lojas pendentes" value={d.lojas_pendentes || 0} icon="◷" /><Stat label="Trocas realizadas" value={d.total_trocas || 0} icon="♻" /><Stat label="Materiais reciclados" value={`${Number(d.total_reciclado_kg || 0).toFixed(1)} kg`} icon="▤" /><Stat label="Créditos distribuídos" value={money(d.total_creditos)} icon="↗" /><Stat label="Resgates" value={d.total_resgates || 0} icon="↘" /><Stat label="CO₂ estimado evitado" value={`~${Number(d.co2_evitado || 0).toFixed(1)} kg`} icon="✳" /></div><Panel title="Materiais neste mês"><div className="material-rates">{materials.map((m, i) => <div key={m}><span>{['📦', '🧴', '🥫', '🍾'][i]}</span><strong>{materialLabels[m]}</strong><small>{Number(d.materiais_mes?.[m] || 0).toLocaleString('pt-BR')} unidades</small></div>)}</div></Panel><Panel title="Atividade recente">{(d.atividades || []).length ? <div className="activity-list">{d.atividades.map((a: any, i: number) => <div key={i}><span className="activity-dot" /><div><strong>{a.descricao}</strong><p>{a.detalhe}</p></div><small>{a.tempo}</small></div>)}</div> : <p className="empty-cell">Nenhuma atividade registrada.</p>}</Panel></>}</>; }
  const resetModal = resetMfa && <ResetMfaModal target={resetMfa} onClose={() => setResetMfa(null)} />;
  if (section === 'usuarios') return <>{resetModal}<PageTitle title="Usuários" description="Gerencie o acesso de clientes à plataforma." /><div className="toolbar"><label className="field-label compact-label">Status<select value={status} onChange={e => setStatus(e.target.value)}><option value="">Todos</option><option value="ativo">Ativo</option><option value="bloqueado">Bloqueado</option><option value="inativo">Inativo</option></select></label></div>{result.loading ? <LoadingBlock /> : <Panel><ErrorBlock error={result.error} /><Table columns={['Cliente', 'E-mail', 'Saldo', 'Trocas', 'Status', 'Ações']} rows={(result.data?.usuarios || []).map((u: any) => [<strong>{u.nome}</strong>, u.email, money(u.saldo), u.total_trocas, <StatusBadge value={u.status} />, <div className="button-row compact">{u.status === 'bloqueado' ? <button className="button subtle small" onClick={() => void act(`/admin/usuarios/${u.id}/desbloquear`)}>Desbloquear</button> : <button className="button warning small" onClick={() => void act(`/admin/usuarios/${u.id}/bloquear`)}>Bloquear</button>}<button className="button subtle small" onClick={() => setResetMfa({ tipo: 'usuario', id: u.id, nome: u.nome })}>Resetar MFA</button><button className="button danger small" onClick={() => void act(`/admin/usuarios/${u.id}`, 'DELETE')}>Remover</button></div>])} /></Panel>}<Pagination page={page} setPage={setPage} hasMore={(result.data?.usuarios || []).length === 20} /> </>;
  if (section === 'resgates') return <><PageTitle title="Pedidos de resgate" description="Revise pedidos pendentes, aprove pagamentos e cancele pedidos inválidos." /><div className="toolbar"><button className="button subtle" onClick={() => void result.reload()}>Atualizar</button></div>{result.loading ? <LoadingBlock /> : <><ErrorBlock error={result.error} /><Panel><Table columns={['ID', 'Cliente', 'Valor', 'Forma', 'Solicitado', 'Status', 'Ações']} rows={(result.data?.resgates || []).map((r: any) => [r.id, <>{r.nome_cliente}<small className="table-sub">#{r.id_cliente}</small></>, money(r.valor), r.forma, dateTime(r.criado_em), <StatusBadge value={r.status} />, <div className="button-row compact">{r.status === 'pendente' && <><button className="button primary small" onClick={() => void act(`/admin/resgates/${r.id}`, 'PATCH', { status: 'aprovado' })}>Aprovar</button><button className="button danger small" onClick={() => void act(`/admin/resgates/${r.id}`, 'PATCH', { status: 'cancelado' })}>Cancelar</button></>}{r.status === 'aprovado' && <button className="button primary small" onClick={() => void act(`/admin/resgates/${r.id}`, 'PATCH', { status: 'pago' })}>Marcar pago</button>}</div>])} empty="Nenhum pedido de resgate." /></Panel></>}</>;
  if (section === 'parceiros') { const stores = result.data?.lojas || []; return <>{resetModal}<PageTitle title="Lojas parceiras" description="Aprove lojas pendentes e acompanhe parceiros ativos." action={<button className="button primary" onClick={() => setShowStoreForm(x => !x)}>+ Cadastrar loja</button>} />{showStoreForm && <Panel title="Cadastrar nova loja"><form className="form-grid" onSubmit={saveStore}>{[['Nome da loja','nome'], ['Responsável','responsavel'], ['E-mail','email'], ['Telefone','telefone'], ['Endereço','endereco'], ['Senha inicial','senha']].map(([label,key]) => <label className="field-label" key={key}>{label}<input required={['nome','responsavel','email','senha'].includes(key)} type={key === 'email' ? 'email' : key === 'senha' ? 'password' : 'text'} value={(storeForm as any)[key]} onChange={e => setStoreForm(v => ({ ...v, [key]: e.target.value }))} /></label>)}<div className="form-actions"><button className="button primary">Cadastrar</button><button type="button" className="button subtle" onClick={() => setShowStoreForm(false)}>Cancelar</button></div></form></Panel>}{result.loading || pendingStores.loading ? <LoadingBlock /> : <><ErrorBlock error={result.error || pendingStores.error} /><Panel title="Aguardando aprovação"><Table columns={['Loja', 'Responsável', 'E-mail', 'Cadastro', 'Ações']} rows={(pendingStores.data?.lojas || []).map((s: any) => [<strong>{s.nome}</strong>, s.responsavel, s.email, dateOnly(s.criado_em), <div className="button-row compact"><button className="button primary small" onClick={() => void act(`/admin/lojas/${s.id}/aprovar`)}>Aprovar</button><button className="button danger small" onClick={() => void act(`/admin/lojas/${s.id}/rejeitar`)}>Rejeitar</button></div>])} empty="Nenhuma loja pendente." /></Panel><Panel title="Parceiros ativos"><Table columns={['Loja', 'Responsável', 'E-mail', 'Trocas', 'Status', 'Ações']} rows={stores.map((s: any) => [<strong>{s.nome}</strong>, s.responsavel, s.email, s.total_trocas, <StatusBadge value={s.status} />, <div className="button-row compact"><button className="button subtle small" onClick={() => setResetMfa({ tipo: 'loja', id: s.id, nome: s.nome })}>Resetar MFA</button><button className="button danger small" onClick={() => void act(`/admin/lojas/${s.id}`, 'DELETE')}>Remover</button></div>])} empty="Nenhum parceiro cadastrado." /></Panel></>}</>; }
  if (section === 'transacoes') return <><PageTitle title="Transações" description="Consulte créditos, débitos e resgates registrados." /><div className="toolbar"><label className="field-label compact-label">Tipo<select value={type} onChange={e => setType(e.target.value)}><option value="">Todos</option><option value="credito">Crédito</option><option value="debito">Débito</option><option value="reciclagem">Reciclagem</option><option value="resgate">Resgate</option></select></label><label className="field-label compact-label">Período<select value={days} onChange={e => setDays(e.target.value)}><option value="7">7 dias</option><option value="30">30 dias</option><option value="90">90 dias</option><option value="365">1 ano</option></select></label><button className="button subtle" onClick={() => void result.reload()}>Atualizar</button></div>{result.loading ? <LoadingBlock /> : <Panel><ErrorBlock error={result.error} /><Table columns={['ID', 'Cliente', 'Loja', 'Descrição', 'Tipo', 'Valor', 'Data']} rows={(result.data?.transacoes || []).map((x: any) => [`#${x.id}`, x.cliente || '—', x.loja || '—', x.materiais || '—', <StatusBadge value={x.tipo} />, money(x.valor), dateTime(x.criado_em)])} /></Panel>}<Pagination page={page} setPage={setPage} hasMore={(result.data?.transacoes || []).length === 20} /></>;
  if (section === 'monitor-qr') return <><PageTitle title="Monitor de QR Code" description="Acompanhe os códigos gerados e invalide códigos ativos." /><div className="toolbar"><label className="field-label compact-label">Status<select value={qrStatus} onChange={e => setQrStatus(e.target.value)}><option value="">Todos</option><option value="ativo">Ativos</option><option value="usado">Usados</option><option value="expirado">Expirados</option><option value="invalido">Inválidos</option></select></label><button className="button subtle" onClick={() => void result.reload()}>Atualizar</button></div>{result.loading ? <LoadingBlock /> : <><ErrorBlock error={result.error} /><div className="stats-grid compact-stats">{[['Ativos', result.data?.metricas?.ativos], ['Usados', result.data?.metricas?.usados], ['Expirados', result.data?.metricas?.expirados], ['Hoje', result.data?.metricas?.total_hoje]].map(([label,value]) => <Stat key={String(label)} label={String(label)} value={Number(value || 0)} icon="▦" />)}</div>{(result.data?.alertas || []).length > 0 && <Panel title="Alertas">{result.data.alertas.map((a: any, i: number) => <div className="alert info" key={i}>{a.tipo}: {a.descricao} · {dateTime(a.data)}</div>)}</Panel>}<Panel title="Códigos"><Table columns={['Transação', 'Loja', 'Valor', 'Criado em', 'Expira em', 'Status', 'Ação']} rows={(result.data?.qrcodes || []).map((q: any) => [<strong>#{q.id_transacao}</strong>, q.nome_loja || `Loja #${q.id_loja}`, money(q.valor), dateTime(q.criado_em), dateTime(q.expira_em), <StatusBadge value={q.status} />, q.status === 'ativo' ? <button className="button danger small" onClick={() => void act('/admin/qrcode/invalidar', 'POST', { id_transacao: q.id_transacao })}>Invalidar</button> : '—'])} /></Panel></>}</>;
  if (section === 'auditoria') return <><PageTitle title="Auditoria de segurança" description="Consulte registros de ações administrativas e eventos da plataforma." /><div className="toolbar"><label className="field-label compact-label">Ação<input value={actionFilter} onChange={e => setActionFilter(e.target.value)} placeholder="Filtrar por ação" /></label><button className="button subtle" onClick={() => void result.reload()}>Atualizar</button></div>{result.loading ? <LoadingBlock /> : <><ErrorBlock error={result.error} /><Panel><Table columns={['ID', 'Ação', 'Cliente', 'Detalhes', 'IP', 'Data']} rows={(result.data?.logs || []).map((l: any) => [l.id, <StatusBadge value={l.acao || 'evento'} />, l.nome_cliente ? <>{l.nome_cliente}<small className="table-sub">{l.email_cliente}</small></> : '—', l.detalhe || '—', l.ip || '—', dateTime(l.criado_em)])} /></Panel><Pagination page={page} setPage={setPage} hasMore={(result.data?.logs || []).length === 20} /></>}</>;
  if (section === 'relatorios') return <><PageTitle title="Relatórios" description="Indicadores consolidados por loja e período." /><div className="toolbar"><label className="field-label compact-label">Mês<input type="month" value={month} onChange={e => setMonth(e.target.value)} /></label><button className="button subtle" onClick={() => void loadReport()}>Atualizar relatório</button><button className="button primary" onClick={() => exportReport(report, month)}>Baixar PDF</button></div>{reportLoading ? <LoadingBlock /> : <><ErrorBlock error={reportError} />{report && <Panel title={`Resumo de ${report.periodo}`}><Table columns={['Loja', 'Responsável', 'Trocas', 'Kg', 'Créditos', 'Resgates', 'Débitos', 'CO₂ estimado']} rows={(report.lojas || []).map((l: any) => [<strong>{l.nome}</strong>, l.responsavel || '—', l.total_trocas, `${Number(l.total_kg || 0).toFixed(1)} kg`, money(l.total_creditos), l.total_resgates, money(l.total_debitos), `~${Number(l.co2_evitado || 0).toFixed(1)} kg`])} empty="Nenhum dado para o período." /></Panel>}</>}</>;
  if (section === 'configuracoes') return <><PageTitle title="Configurações" description="Ajuste taxas de conversão e parâmetros de QR Code." />{result.loading ? <LoadingBlock /> : <><ErrorBlock error={result.error} /><Panel title="Taxas de conversão"><p className="muted">Unidades de material necessárias para gerar R$ 0,25. O servidor recalcula o crédito.</p><form className="form-grid" onSubmit={saveTaxes}>{materials.map(m => <label className="field-label" key={m}>{materialLabels[m]} — unidades por R$ 0,25<input type="number" min="1" max="10000" value={taxes[m]} onChange={e => setTaxes(v => ({ ...v, [m]: Number(e.target.value) }))} /></label>)}<div className="form-actions"><button className="button primary">Salvar taxas</button></div></form></Panel><Panel title="Configurações de QR"><p className="muted">A configuração de validade é aplicada pelo backend. A API atual não expõe leitura dos valores já salvos; os campos abaixo iniciam com os padrões documentados.</p><form className="form-grid" onSubmit={saveQr}><label className="field-label">Expiração em segundos<input type="number" min="1" max="300" value={qrConfig.expiracao_segundos} onChange={e => setQrConfig(v => ({ ...v, expiracao_segundos: Number(e.target.value) }))} /></label><label className="field-label">Máximo de tentativas inválidas<input type="number" min="1" max="20" value={qrConfig.max_tentativas} onChange={e => setQrConfig(v => ({ ...v, max_tentativas: Number(e.target.value) }))} /></label><div className="form-actions"><button className="button primary">Salvar QR</button></div></form></Panel></>}</>;
  return <Navigate to="/app/admin/dashboard" replace />;
}
function Pagination({ page, setPage, hasMore }: { page: number; setPage: (n: number) => void; hasMore: boolean }) { return <div className="pagination"><button className="button subtle small" disabled={page <= 1} onClick={() => setPage(page - 1)}>← Anterior</button><span>Página {page}</span><button className="button subtle small" disabled={!hasMore} onClick={() => setPage(page + 1)}>Próxima →</button></div>; }
function StatusBadge({ value }: { value: string }) { return <span className={`badge badge-${String(value).toLowerCase().replace(/[^a-z0-9]/g, '-')}`}>{value}</span>; }
async function exportReport(report: any, month: string) { if (!report?.lojas?.length) { notify('Não há dados para exportar.', 'error'); return; } const { default: JsPDF } = await import('jspdf'); const doc = new JsPDF(); doc.setFontSize(18); doc.setTextColor(17, 86, 57); doc.text('CrisoVerde — Relatório de Lojas', 14, 18); doc.setFontSize(11); doc.setTextColor(60); doc.text(`Período: ${month}`, 14, 27); let y = 39; for (const l of report.lojas) { if (y > 270) { doc.addPage(); y = 20; } doc.setFontSize(13); doc.setTextColor(17, 86, 57); doc.text(l.nome, 14, y); y += 7; doc.setFontSize(10); doc.setTextColor(50); const lines = [`Responsável: ${l.responsavel || '—'}`, `Trocas: ${l.total_trocas} · Materiais: ${Number(l.total_kg || 0).toFixed(1)} kg`, `Créditos: ${money(l.total_creditos)} · Débitos: ${money(l.total_debitos)}`, `Resgates: ${l.total_resgates} · CO₂ estimado: ${Number(l.co2_evitado || 0).toFixed(1)} kg`]; lines.forEach(line => { doc.text(line, 14, y); y += 6; }); y += 5; } doc.save(`crisoverde-relatorio-${month}.pdf`); }

type CookiePrefs = { essential: true; analytics: boolean; marketing: boolean; updatedAt: string };
function readCookie(name: string) { return document.cookie.split('; ').find(c => c.startsWith(`${name}=`))?.split('=').slice(1).join('=') || ''; }
function writeConsent(prefs: CookiePrefs) { const secure = location.protocol === 'https:' ? '; Secure' : ''; document.cookie = `cv_cookie_consent=${encodeURIComponent(JSON.stringify(prefs))}; Max-Age=${180 * 24 * 60 * 60}; Path=/; SameSite=Lax${secure}`; window.dispatchEvent(new Event('cookie-consent-updated')); }
function CookieConsent() {
  const [visible, setVisible] = useState(false); const [settings, setSettings] = useState(false); const [analytics, setAnalytics] = useState(false); const [marketing, setMarketing] = useState(false);
  useEffect(() => { const raw = readCookie('cv_cookie_consent'); if (raw) { try { const p = JSON.parse(decodeURIComponent(raw)) as CookiePrefs; setAnalytics(Boolean(p.analytics)); setMarketing(Boolean(p.marketing)); } catch { setVisible(true); } } else setVisible(true);
    const open = () => setSettings(true); const updated = () => { setVisible(false); setSettings(false); }; window.addEventListener('open-cookie-settings', open); window.addEventListener('cookie-consent-updated', updated); return () => { window.removeEventListener('open-cookie-settings', open); window.removeEventListener('cookie-consent-updated', updated); };
  }, []);
  if (!visible && !settings) return null;
  const save = (all: boolean) => writeConsent({ essential: true, analytics: all ? true : analytics, marketing: all ? true : marketing, updatedAt: new Date().toISOString() });
  return <>{visible && <aside className="cookie-banner" aria-label="Preferências de cookies"><div><strong>Privacidade e cookies</strong><p>Usamos cookies necessários para manter a sessão segura. Não há analytics nem cookies de marketing ativos neste pacote. <Link to="/privacidade">Saiba mais</Link></p></div><div className="cookie-actions"><button className="button subtle small" onClick={() => setSettings(true)}>Configurar</button><button className="button subtle small" onClick={() => save(false)}>Rejeitar opcionais</button><button className="button primary small" onClick={() => save(true)}>Aceitar opcionais</button></div></aside>}
    {settings && <div className="modal-backdrop" role="presentation" onMouseDown={e => e.target === e.currentTarget && setSettings(false)}><section className="modal-card cookie-modal" role="dialog" aria-modal="true" aria-labelledby="cookie-title"><button className="close-button" onClick={() => setSettings(false)} aria-label="Fechar">×</button><h2 id="cookie-title">Preferências de cookies</h2><p className="muted">Você pode alterar sua escolha a qualquer momento pelo link “Preferências de cookies”.</p><div className="preference-row"><div><strong>Necessários</strong><p>Usados para sessão/autenticação e para guardar sua escolha de cookies. Sempre ativos.</p></div><span className="badge badge-ativo">Ativos</span></div><label className="preference-row"><div><strong>Analytics</strong><p>Não há ferramenta analítica instalada no app recebido. Esta preferência não ativa scripts enquanto não houver integração.</p></div><input type="checkbox" checked={analytics} onChange={e => setAnalytics(e.target.checked)} /></label><label className="preference-row"><div><strong>Marketing</strong><p>Não há ferramenta de marketing instalada. Esta preferência não ativa scripts enquanto não houver integração.</p></div><input type="checkbox" checked={marketing} onChange={e => setMarketing(e.target.checked)} /></label><button className="button primary full" onClick={() => save(false)}>Salvar preferências</button></section></div>}</>;
}
function PrivacyPage() {
  return <main className="legal-layout"><header className="legal-top"><Link to="/" className="brand-link"><Brand /></Link><Link to="/" className="button subtle">Voltar ao app</Link></header><article className="legal-document"><span className="eyebrow">CrisoVerde · Documento informativo</span><h1>Privacidade e cookies</h1><p className="legal-date">Versão 1.0 · Atualizada em 23/10/2026</p><div className="alert info"><strong>Informações pendentes para publicação:</strong> esta versão descreve apenas o comportamento técnico confirmado no projeto. O controlador, canal de privacidade, bases legais, fornecedores, prazos de retenção e contato ainda precisam ser preenchidos e revisados pelo responsável antes da publicação definitiva.</div>
    <h2>1. Quem trata os dados</h2><p>Controlador: <strong>[PREENCHER NOME/RAZÃO SOCIAL]</strong>. CNPJ e endereço: <strong>[PREENCHER]</strong>. Canal de privacidade: <strong>[PREENCHER E-MAIL OU CANAL]</strong>. Não foi possível confirmar esses dados nos arquivos fornecidos.</p>
    <h2>2. Dados tratados pelo sistema</h2><p>O backend recebido contém cadastro de nome, e-mail e telefone; dados de sessão e autenticação; saldo e totais da carteira; operações de reciclagem, resgate e uso de QR; dados cadastrais de lojas; registros de auditoria e dados técnicos de rate limiting. O uso de Google e e-mail transacional depende da configuração de credenciais. O projeto não confirma quais serviços estão ativos.</p>
    <h2>3. Finalidades e bases legais</h2><p>As finalidades técnicas observáveis incluem criar e autenticar contas, manter sessões, registrar carteiras e transações, validar QR Codes, recuperar senhas e proteger o serviço contra abuso. As bases legais adequadas a cada finalidade devem ser confirmadas pelo controlador e revisadas juridicamente: <strong>[PREENCHER/VALIDAR]</strong>.</p>
    <h2>4. Cookies e armazenamento local</h2><ul><li><strong>Cookie de sessão `crisoverde_session`:</strong> definido pelo backend com HttpOnly e SameSite=Strict; necessário para autenticação e operações protegidas. Em produção HTTPS, Secure é aplicado pelo backend.</li><li><strong>Cookie `cv_cookie_consent`:</strong> guarda a escolha de preferências por até 180 dias, SameSite=Lax, necessário para lembrar a decisão.</li><li><strong>Cookies opcionais:</strong> o pacote analisado não instala analytics ou marketing. As opções correspondentes ficam desativadas por padrão; escolhê-las não ativa scripts que não estão instalados.</li><li>Credenciais, sessão e tokens não são guardados em localStorage/sessionStorage pela interface React.</li></ul>
    <h2>5. Compartilhamento e transferências</h2><p>O código contém integração opcional com Google OAuth e Resend, porém não foi comprovado que estejam habilitadas nem quais dados são enviados em produção. Fornecedores, países de tratamento e transferências internacionais: <strong>[CONFIRMAR ANTES DA PUBLICAÇÃO]</strong>.</p>
    <h2>6. Retenção e segurança</h2><p>O sistema mantém registros de conta, transações e auditoria no PostgreSQL e utiliza cookies de sessão. Prazos de retenção, rotinas de eliminação, backups e responsáveis pelo acesso dependem da configuração operacional, não confirmada no pacote. Definir e documentar: <strong>[PREENCHER PRAZOS E PROCESSOS]</strong>.</p>
    <h2>7. Direitos e solicitações</h2><p>Para exercer direitos relacionados a dados pessoais, use o canal oficial que o controlador deverá informar: <strong>[PREENCHER CONTATO]</strong>. O controlador deve definir o processo de atendimento, validação de identidade, prazos aplicáveis e tratamento de solicitações.</p>
    <h2>8. Alterações e aprovação</h2><p>Esta página é uma base técnica e não substitui revisão jurídica. Data de vigência e histórico de versões devem ser confirmados pelo controlador. Não publicar como política final até preencher os campos pendentes e aprovar o conteúdo.</p>
    <h2>9. Preferências de cookies</h2><p>Você pode revisar ou retirar sua escolha pelo botão abaixo. Cookies estritamente necessários continuam ativos para a autenticação e a segurança do sistema.</p><button className="button primary" onClick={() => window.dispatchEvent(new Event('open-cookie-settings'))}>Configurar cookies</button>
  </article><footer className="legal-footer">CrisoVerde · <Link to="/login">Entrar</Link></footer></main>;
}
